// P Case packing
// Generated by compiler/emit.js from lines/bottlingRehearsal/factory.json.
// Do not edit: change the factory.json and compile again (npm run compile).
//
// Cycle 10.48 s (intake 3.24 + process 4.00 + output 3.24), 4 steps
// (a decision on a fact only known while a unit plays is timed by its planAs branch, else its longest).
// Equipment, in the station's own frame (metres; product flows +X, conveyor on z = 0, walkway +Z):
//   id       type            from     position   turn
//   belt     beltConveyor    station  [0, 0, 0]
//   machine  genericMachine  station  [0, 0, 0]
import * as THREE from 'three';

/** What the station does (played by lib/station/StationCycle.js): ports, process ops, status, signals. */
export const station = {
  id: 'pack',
  code: 'P',
  title: 'Case packing',
  workState: 'WORKING',
  inputStage: 'capped',
  conveyor: 'belt',
  ports: {},
  intake: [
    {
      op: 'transfer',
      conveyor: 'belt',
      to: { machine: 'machine', port: 'work' },
      label: 'Into the case packer',
    },
  ],
  process: [{ op: 'operate', machine: 'machine', seconds: 4, label: 'Case packer' }],
  output: [{ op: 'transfer', conveyor: 'belt', to: 'output', label: 'Bottle out' }],
  home: {},
  stock: {},
  stacks: {},
  status: {},
  signals: {},
  feed: { fromLift: false },
};

/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'P Case packing';
  const equipment = {};

  // belt: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.belt = registry.buildComponent('beltConveyor', { length: 2.6 }, ctx);
  root.add(equipment.belt.root);

  // machine: Placeholder for a machine not in the catalog: an enclosure with the right...
  equipment.machine = registry.buildComponent('genericMachine', {
    name: 'Case packer',
    note: '6 bottles per case',
    length: 1.4,
    depth: 0.9,
  }, ctx);
  root.add(equipment.machine.root);

  return { root, equipment };
}
